  tableOf(S["02_HopDong"]).filter(r=>/^NV/.test(r["Mã NS"]||"")).forEach(r=>{const x=out.ns[r["Mã NS"]]=out.ns[r["Mã NS"]]||{};x.hd={loai:String(r["Loại HĐ"]||""),so:String(r["Số HĐ"]||""),ky:dstr(r["Ngày ký"]),hieuLuc:dstr(r["Ngày hiệu lực"]),het:dstr(r["Ngày hết hạn"]),hetTV:dstr(r["Ngày hết thử việc"]),luongTV:nv(r["Lương thử việc"]),luongCT:nv(r["Lương chính thức"]),giay:String(r["Đã ký bản giấy"]||"")}});
  tableOf(S["04_NghiPhep"]).filter(r=>/^NV/.test(r["Mã NS"]||"")).forEach(r=>{out.phep[r["Mã NS"]]={chuan:nv(r[Object.keys(r).find(k=>/tiêu chuẩn/.test(k))]),huong:nv(r["Phép được hưởng"]),da:nv(r["Đã nghỉ phép"]),kl:nv(r["Nghỉ không lương"]),om:nv(r["Nghỉ ốm"])}});
  tableOf(S["05_KPI"]).filter(r=>/^NV/.test(r["Mã NS"]||"")).forEach(r=>{const ks=Object.keys(r);const ct=[1,2,3].map(i=>[String(r["Chỉ tiêu "+i]||""),nv(r["KQ "+i]),nv(r["Trọng số "+i])]).filter(x=>x[0]);out.kpi.push({id:uid("kp"),thang:dstr(r["Tháng"]).slice(0,7),ma:r["Mã NS"],ct,diem:nv(r["Điểm KPI"]),xl:String(r["Xếp loại"]||""),st:/Đã/.test(r["Lead xác nhận"]||"")?"duyet":"cho",nguon:"file"})});
