  const h=HRD(),L=D().staff.filter(x=>h.ns[x.ma]&&h.ns[x.ma].hd).map(x=>({x,hd:h.ns[x.ma].hd})).map(o=>({...o,con:daysTo(o.hd.het),tv:daysTo(o.hd.hetTV)})).sort((a,b)=>(a.con??9999)-(b.con??9999));
